xql_query:
// ============================================================
// Rule: WIN_Mass Account Disablement by SailPoint Service Account
// Vendor: Windows
// Objective:
// Detect activity associated with WIN_Mass Account Disablement by SailPoint Service Account.
// Severity: SEV_040_HIGH
// Category: CREDENTIAL_ACCESS
// ============================================================
// SANITIZED: Environment-specific values replaced with generic placeholders.
// MITRE ATT&CK:
// Tactic: TA0040 - Impact
// Technique: T1531 - Account Access Removal

// Objetivo:
// etectar quando a conta de serviço <IDENTITY_PROVISIONING_ACCOUNT> desativar
// 200 ou mais contas distintas do Active Directory dentro
// de um período de 1 hora.
// Evento monitorado:
// Windows Security Event ID 4725
// "A user account was disabled"
// ============================================================


// Comparações de texto não diferenciam maiúsculas/minúsculas
config case_sensitive = false


// Fonte de dados: telemetria do Cortex, incluindo Windows Event Log
| dataset = xdr_data


// Mantém somente eventos do Windows Event Log
| filter event_type = ENUM.EVENT_LOG


// Event ID 4725 = uma conta foi desativada
| filter action_evtlog_event_id = 4725


// Extração e normalização dos campos do evento
| alter
    DisabledUser     = action_evtlog_data_fields -> TargetUserName,
    DisabledUserSid  = action_evtlog_data_fields -> TargetSid,
    TargetDomain     = action_evtlog_data_fields -> TargetDomainName,
    ExecutorUser     = action_evtlog_data_fields -> SubjectUserName,
    ExecutorDomain   = action_evtlog_data_fields -> SubjectDomainName,
    SubjectLogonId   = action_evtlog_data_fields -> SubjectLogonId


// Considera somente desativações realizadas pela conta do SailPoint
| filter ExecutorUser = "<IDENTITY_PROVISIONING_ACCOUNT>"


// Remove eventos sem identificação da conta desativada
| filter DisabledUser != null
| filter DisabledUser != ""


// Consolida todos os eventos encontrados no período configurado
// na Correlation Rule.
//
// Não agrupamos por agent_hostname para evitar dividir a contagem
// caso o SailPoint execute operações em diferentes Domain Controllers.
| comp
    count() as disable_events,
    count_distinct(DisabledUser) as disabled_accounts,
    values(DisabledUser) as disabled_users,
    values(DisabledUserSid) as disabled_user_sids,
    values(agent_hostname) as domain_controllers,
    earliest(_time) as first_disable_time,
    latest(_time) as last_disable_time
  by ExecutorDomain, ExecutorUser, TargetDomain


// Threshold: 200 ou mais contas distintas desativadas
| filter disabled_accounts >= 200


// Destaca os maiores volumes
| sort desc disabled_accounts


// Campos apresentados no alerta
| fields
    first_disable_time,
    last_disable_time,
    ExecutorDomain,
    ExecutorUser,
    TargetDomain,
    disabled_accounts,
    disable_events,
    disabled_users,
    disabled_user_sids,
    domain_controllers
